constexpr auto writers=callbacks(std::make_index_sequence<max_controls>{});
template<size_t I>void __stdcall scroll_callback(int top,int rows,int buffer){if(controls[I])controls[I]->accept_scroll(top,rows,buffer);}
template<size_t... I>constexpr auto scroll_callbacks(std::index_sequence<I...>){return std::array<void(__stdcall*)(int,int,int),sizeof...(I)>{scroll_callback<I>...};}
constexpr auto scrollers=scroll_callbacks(std::make_index_sequence<max_controls>{});
