DWORD run_remote(HANDLE process,LPTHREAD_START_ROUTINE routine,void*argument){Handle thread(CreateRemoteThread(process,nullptr,0,routine,argument,0,nullptr));check(static_cast<bool>(thread),"Initialize owned Plink adapter");check(WaitForSingleObject(thread.get(),15000)==WAIT_OBJECT_0,"Wait for owned adapter initialization");DWORD result=0;check(GetExitCodeThread(thread.get(),&result)!=FALSE,"Read adapter status");return result;}
