TerminalControl::TerminalControl()=default;
TerminalControl::~TerminalControl(){if(terminal_){if(IsWindow(window_)){KillTimer(window_,77);RemoveWindowSubclass(window_,subclass,1);}api_->destroy(terminal_);}if(slot_<controls.size()&&controls[slot_]==this)controls[slot_]=nullptr;}
