void PasswordPipe::cancel()noexcept{std::lock_guard lock(mutex_);if(cancel_)SetEvent(cancel_.get());if(pipe_)CancelIoEx(pipe_.get(),nullptr);}
std::string PasswordPipe::error(){std::lock_guard lock(mutex_);return error_;}
